   "lead": "Secondo il Cremlino, nella telefonata con Donald Trump Vladimir Putin ha ridimensionato la possibilità di una ripresa immediata dei colloqui sull'Ucraina. I due hanno discusso anche di importanti iniziative economiche, tra cui possibili forniture di carburante russo. Il portavoce Dmitrij Peskov ha aggiunto che gran parte della conversazione ha riguardato l'Ucraina e che Putin ha risposto con comprensione ad alcune proposte americane di de-escalation.",
