   "lead": "Il presidente della Repubblica portoghese, António José Seguro, ha affermato che la salute mentale non può continuare a essere relegata in secondo piano e deve essere accessibile a tutti nelle strutture sanitarie, nelle scuole e nei luoghi di lavoro, puntando sulla prevenzione. Secondo Público, la considera un diritto umano universale, non un lusso né una questione soltanto privata.",
