   "orig": "Four families, four stories of separation. The authors of ‘Stolen Youth,’ a new book from Meduza about how Russia abducted thousands of Ukrainian children, explain why they wrote it.",
   "lead": "Gli autori di «Stolen Youth», nuovo libro di Meduza, spiegano perché l'hanno scritto. Dall'inizio dell'invasione su vasta scala nel 2022 migliaia di bambini ucraini sono finiti in Russia, con scenari diversi: alcuni fuggendo dalla zona dei combattimenti, altri portati via dai territori occupati. Il libro segue quattro famiglie. Lo riferisce Meduza.",
