   "lead": "Il presidente palestinese Mahmoud Abbas ha rinviato all'11 settembre 2027 le elezioni legislative previste per il prossimo novembre e ha fissato per lo stesso giorno quelle presidenziali. Il decreto cita gli ostacoli posti dalle misure israeliane e la situazione di sicurezza nei territori palestinesi.",
