   "lead": "Un attacco ha colpito sabato l'aeroporto internazionale King Khalid di Riad, la capitale saudita, e ha lasciato diversi feriti. Le autorità hanno sospeso le operazioni dello scalo e i voli sono stati dirottati o cancellati. L'ambasciata americana dice di essere al corrente degli attacchi, arrivati pochi giorni dopo la rivendicazione di un colpo allo stesso aeroporto da parte degli Houthi yemeniti.",
