    "Sul numero dei feriti le cronache non coincidono: la BBC e la CBC parlano di «diversi» o «molti» feriti, Le Figaro di «decine», mentre la radio portoghese RTP, sempre sulla base dell'AFP, riferisce di cinque persone in terapia intensiva. La responsabilità dell'attacco è attribuita agli Houthi dalle testate francesi, ma i dettagli vengono da fonti anonime e non sono verificati in modo indipendente."
