   "lead": "Un terremoto di magnitudo 7,7 ha colpito il sud di Panama venerdì mattina, con epicentro vicino a Tonosí. Ha danneggiato edifici e strade e mandato migliaia di persone in strada, ma il Paese sembra essere stato risparmiato da distruzioni estese. Il bilancio provvisorio diffuso dalle autorità e riportato dall'ANSA parla di almeno 27 feriti lievi e oltre 400 edifici danneggiati; i voli, sospesi per un breve periodo, sono ripresi.",
