    "L'ANSA riferisce che alcuni piani dell'abitazione dell'ex presidente Martinelli sono crollati. Il Centro di allerta per gli tsunami degli Stati Uniti ha poi comunicato, secondo RNZ, che non c'era più alcuna minaccia per le isole del Pacifico. Il bilancio è ancora provvisorio."
